/**
 * Helper to create a valid encoded beacon with consistent values.
 *
 * Ensures payloadLen and originalSize are consistent with blockCount × blockSize
 * to avoid overflow and validation errors.
 */
function createEncodedBeacon(overrides: Partial<BeaconMeta>): Uint8Array {
  const meta = {...createValidMeta(), ...overrides};

  // Ensure consistency between blockCount, blockSize, and payloadLen
  // Always recalculate from blockCount × blockSize to ensure consistency
  if (typeof meta.blockCount === 'number' && typeof meta.blockSize === 'number') {
    const calculatedSize = meta.blockCount * meta.blockSize;

    // Check for overflow before using the calculated size
    if (!Number.isSafeInteger(calculatedSize)) {
      throw new Error(`Block size overflow: blockCount=${meta.blockCount} × blockSize=${meta.blockSize} exceeds safe integer range`);
    }

    // Use the calculated size for both originalSize and payloadLen
    // This ensures the beacon fields are internally consistent
    meta.originalSize = calculatedSize;
    meta.payloadLen = calculatedSize;
  }

  return encodeBeacon(meta);
}

